/* Banco de perguntas da prova de gramática.
   {id, topic (id de data/grammar.js, mesmo nível), kind: particula|forma|traducao|leitura|conceito,
    q, opts (4), ans (índice da única correta), why}
   q, opts e why aceitam a marcação do grammar.js: **negrito** e {漢字|かな}. */
const GRAMMAR_QUIZ = {
basico: [
{id:"b001",topic:"hiragana",kind:"conceito",q:"Quantos sons básicos tem o hiragana, e o que cada letra representa?",opts:["46 sons; cada letra é uma sílaba","26 sons; cada letra é uma letra solta, como no português","46 sons; cada letra é uma palavra inteira","Cerca de 2.000 sons; cada letra é uma ideia"],ans:0,why:"O hiragana tem 46 letras básicas e cada uma é uma **sílaba** (か = ka), e não uma letra solta como em português."},
{id:"b002",topic:"hiragana",kind:"leitura",q:"Como se lê a partícula は em わたしは がくせいです? Escolha a letra que tem o mesmo som.",opts:["は","わ","ほ","お"],ans:1,why:"Como partícula, は lê-se **wa**, o mesmo som de わ. A letra continua sendo escrita は."},
{id:"b003",topic:"hiragana",kind:"conceito",q:"Para que o hiragana é usado principalmente?",opts:["Para escrever palavras de origem estrangeira","Para escrever só nomes de pessoas","Para escrever palavras sem kanji, partículas e terminações de verbos","Para escrever apenas números"],ans:2,why:"O hiragana escreve palavras japonesas sem kanji e toda a gramática: partículas (は, を, の…) e terminações de verbos. As palavras estrangeiras ficam com o katakana."},
{id:"b004",topic:"katakana",kind:"conceito",q:"Qual é o uso principal do katakana?",opts:["Escrever as partículas da frase","Mostrar como ler um kanji","Escrever as terminações dos verbos","Escrever palavras de outras línguas, como コーヒー"],ans:3,why:"O katakana escreve palavras estrangeiras (コーヒー, テレビ), nomes de fora do Japão e onomatopeias. Partículas e terminações ficam no hiragana."},
{id:"b005",topic:"katakana",kind:"traducao",q:"O que significa パン?",opts:["Pão","Café","Táxi","Hotel"],ans:0,why:"パン é “pão”. Os outros são コーヒー (café), タクシー (táxi) e ホテル (hotel)."},
{id:"b006",topic:"katakana",kind:"forma",q:"Qual sinal alonga a vogal no katakana, como em コーヒー?",opts:["っ","ー","゛","゜"],ans:1,why:"O traço **ー** alonga a vogal anterior e só existe no katakana. O っ pequeno dobra a consoante, e ゛ e ゜ mudam o som da letra."},
{id:"b007",topic:"dakuten",kind:"forma",q:"Qual letra resulta de acrescentar o dakuten (゛) a か?",opts:["ぱ","ま","が","ぎ"],ans:2,why:"O dakuten transforma k em g: か → が. O ぎ vem de き, e o ぱ só existe na linha は (com handakuten)."},
{id:"b008",topic:"dakuten",kind:"forma",q:"Qual sinal transforma は em ぱ?",opts:["O dakuten (゛, dois tracinhos)","O っ pequeno","O traço ー","O handakuten (゜, um círculo)"],ans:3,why:"O handakuten (゜) troca h por p, e só a linha は o aceita. O dakuten transformaria は em ば."},
{id:"b009",topic:"dakuten",kind:"leitura",q:"Qual destas palavras é escrita com uma letra de handakuten (゜)?",opts:["えんぴつ (lápis)","がくせい (estudante)","でんわ (telefone)","かばん (bolsa)"],ans:0,why:"Só えんぴつ tem ぴ, que leva o handakuten. Em がくせい, でんわ e かばん, as letras が, で e ば levam dakuten."},
{id:"b010",topic:"sons-especiais",kind:"conceito",q:"Qual é a diferença entre おばさん e おばあさん?",opts:["São a mesma palavra escrita de dois jeitos","おばさん é tia e おばあさん é avó: a vogal longa muda a palavra","おばさん é avó e おばあさん é tia","Só muda o nível de educação"],ans:1,why:"A vogal longa (o あ escrito de novo) dobra a duração do som e muda o significado: おばさん (tia) e おばあさん (avó)."},
{id:"b011",topic:"sons-especiais",kind:"forma",q:"O que faz o っ pequeno em きって?",opts:["Alonga a vogal anterior","Transforma o t em d","Cria uma pausa curtíssima que dobra a consoante seguinte","Não muda nada: é só enfeite"],ans:2,why:"O っ pequeno é uma pausa curtíssima que faz a consoante seguinte soar dobrada (kit-te). Ele vale uma batida."},
{id:"b012",topic:"sons-especiais",kind:"forma",q:"Quantas batidas (moras) tem きょう (hoje)?",opts:["1","3","4","2"],ans:3,why:"きょ vale **uma** batida (o ょ pequeno forma uma sílaba só com o き) e う vale outra: são 2 batidas."},
{id:"b013",topic:"escrita",kind:"conceito",q:"Em {飲|の}む, qual é o papel do む?",opts:["É o okurigana: a terminação do verbo, escrita em hiragana","É o furigana, que mostra a leitura","É uma partícula","É outro kanji, só que simplificado"],ans:0,why:"O kanji traz o sentido, e o hiragana que o acompanha (む) é o **okurigana**, a terminação do verbo. O furigana é o kana pequeno escrito em cima do kanji."},
{id:"b014",topic:"escrita",kind:"conceito",q:"Qual escrita se usa para palavras estrangeiras, como ホテル?",opts:["Hiragana","Katakana","Kanji","Furigana"],ans:1,why:"O katakana escreve palavras que vieram de outras línguas e nomes estrangeiros."},
{id:"b015",topic:"escrita",kind:"conceito",q:"No japonês normal, como se percebe onde cada palavra começa e termina?",opts:["Há um espaço entre as palavras, como no português","Há uma vírgula depois de cada palavra","Não há espaços: a mistura de kanji e kana ajuda a separar as palavras","Cada palavra é escrita numa linha separada"],ans:2,why:"O japonês normal não usa espaços. Os espaços dos exemplos em hiragana são só um recurso para quem está começando."},
{id:"b016",topic:"desu",kind:"forma",q:"Como se diz “Eu não sou estudante”?",opts:["わたしは がくせいません。","わたしは がくせいくないです。","わたしは がくせいじゃありませんでした。","わたしは がくせいじゃありません。"],ans:3,why:"O negativo de です com substantivo é **じゃありません**. ません é de verbos, e くないです é de adjetivos い. じゃありませんでした seria passado (“não era”)."},
{id:"b017",topic:"desu",kind:"conceito",q:"Em きょうは あついです, qual é a função do です?",opts:["Dar educação à frase: o adjetivo já carrega a ideia de “estar”","Ser o verbo “ter”","Marcar o tema da frase","Transformar a frase em pergunta"],ans:0,why:"Depois de adjetivo, o です só acrescenta educação. O sentido de “estar quente” já está em あつい. O tema é marcado por は, e a pergunta, por か."},
{id:"b018",topic:"desu",kind:"forma",q:"Como se diz “Ontem foi dia de chuva”?",opts:["きのうは あめです。","きのうは あめでした。","きのうは あめじゃありません。","きのうは あめました。"],ans:1,why:"O passado de です é **でした**. です é presente, じゃありません é negativo, e ました pertence aos verbos."},
{id:"b019",topic:"wa-mo-ka",kind:"particula",q:"Complete com a partícula certa: やまださん___ がくせいです。 (Yamada-san também é estudante.)",opts:["は","か","も","の"],ans:2,why:"**も** quer dizer “também” e ocupa o lugar do は. Com は, a frase só diria “Yamada-san é estudante”, sem a ideia de “também”."},
{id:"b020",topic:"wa-mo-ka",kind:"forma",q:"Como se transforma “ここは がっこうです” em pergunta?",opts:["Trocando は por か: ここか がっこうです","Acrescentando は no fim: ここは がっこうです は","Invertendo a ordem das palavras","Acrescentando か no fim: ここは がっこうですか"],ans:3,why:"Para perguntar, basta acrescentar **か** no fim da frase. Não é preciso mudar a ordem das palavras nem usar ponto de interrogação."},
{id:"b021",topic:"wa-mo-ka",kind:"conceito",q:"Qual é a função de は em きょうは にちようびです?",opts:["Marcar o tema: aquilo sobre o que se fala","Marcar o objeto do verbo","Ser o artigo “o/a”","Indicar o lugar"],ans:0,why:"は marca o **tema** (“quanto a hoje…”). Não é artigo, e o objeto do verbo é marcado por を."},
{id:"b022",topic:"no",kind:"traducao",q:"Como se diz “livro de japonês”?",opts:["ほんの にほんご","にほんごの ほん","にほんごを ほん","にほんごで ほん"],ans:1,why:"Em **A の B**, vem primeiro o tipo (にほんご) e depois a coisa (ほん). A ordem é o contrário do português."},
{id:"b023",topic:"no",kind:"particula",q:"Complete: これは わたし___ かばんです。 (Esta é a minha bolsa.)",opts:["を","で","の","か"],ans:2,why:"O **の** liga dois substantivos e indica posse: わたしの かばん (a minha bolsa)."},
{id:"b024",topic:"no",kind:"traducao",q:"O que quer dizer だれの かばんですか。",opts:["Quem tem a bolsa?","Onde está a bolsa?","Que bolsa é esta?","De quem é a bolsa?"],ans:3,why:"だれの quer dizer “de quem”. A frase pergunta a quem pertence a bolsa."},
{id:"b025",topic:"kosoado",kind:"conceito",q:"A pessoa ao seu lado está segurando um livro e você pergunta o que é. Qual palavra completa a frase? ___は なんですか。",opts:["それ","これ","あれ","どれ"],ans:0,why:"**それ** aponta algo perto de **quem ouve**. これ seria algo perto de você, あれ, algo longe dos dois, e どれ pergunta “qual?”."},
{id:"b026",topic:"kosoado",kind:"forma",q:"Como se diz “este livro”?",opts:["これ ほん","この ほん","ここ ほん","どれ ほん"],ans:1,why:"Antes de um substantivo usa-se **この / その / あの**. これ, それ e あれ nunca vêm junto de um substantivo."},
{id:"b027",topic:"kosoado",kind:"traducao",q:"Como se pergunta “Onde fica o banheiro?”",opts:["トイレは どれですか。","トイレは だれですか。","トイレは どこですか。","トイレは あれですか。"],ans:2,why:"**どこ** pergunta “onde”. どれ é “qual”, だれ é “quem”, e あれですか perguntaria “é aquilo”."},
{id:"b028",topic:"adj-i",kind:"forma",q:"Como se diz “Ontem estava quente”?",opts:["きのうは あついでした。","きのうは あつでした。","きのうは あつくないです。","きのうは あつかったです。"],ans:3,why:"O passado está **no adjetivo**: あつい → あつかった, e o です só dá educação. あついでした é o erro típico."},
{id:"b029",topic:"adj-i",kind:"forma",q:"Qual é o negativo educado de たかいです (é caro)?",opts:["たかくないです","たかいじゃありません","たかいません","たかないです"],ans:0,why:"No adjetivo い, troca-se o い por **くない**: たかくないです. じゃありません serve para substantivos, e ません, para verbos."},
{id:"b030",topic:"adj-i",kind:"forma",q:"Qual destas frases está errada?",opts:["きょうは あつくないです。","この ほんは たかいです。","きのうは たかいでした。","あつい コーヒー"],ans:2,why:"O passado do adjetivo い é feito no próprio adjetivo: たかかったです. たかいでした está errado."},
{id:"b031",topic:"adj-na",kind:"forma",q:"Complete: ___ まち (cidade tranquila)",opts:["しずかい","しずかな","しずかく","しずかの"],ans:1,why:"Antes de um substantivo, o adjetivo な ganha **な**: しずかな まち."},
{id:"b032",topic:"adj-na",kind:"forma",q:"Como se diz “Aqui não é tranquilo”?",opts:["ここは しずかくないです。","ここは しずかなじゃありません。","ここは しずかじゃありません。","ここは しずかません。"],ans:2,why:"O adjetivo な se conjuga como substantivo + です: しずか**じゃありません**. くないです é de adjetivo い, e o な não aparece no fim da frase."},
{id:"b033",topic:"adj-na",kind:"forma",q:"きれい termina em い, mas é adjetivo な. Como se diz “flor bonita”?",opts:["きれい はな","きれかった はな","きれくない はな","きれいな はな"],ans:3,why:"Como adjetivo な, o きれい pede **な** antes do substantivo: きれいな はな."},
{id:"b034",topic:"masu",kind:"forma",q:"Qual é a forma ます de のむ (beber)?",opts:["のみます","のむます","のまます","のんます"],ans:0,why:"No grupo 1, troca-se a última sílaba pela da coluna い: のむ → の**み**ます."},
{id:"b035",topic:"masu",kind:"forma",q:"Como se diz “Eu não comi”?",opts:["たべません。","たべませんでした。","たべました。","たべじゃありませんでした。"],ans:1,why:"O passado negativo é **ませんでした**. ません é o negativo no presente, ました é o passado afirmativo, e じゃありません não se usa com verbos."},
{id:"b036",topic:"masu",kind:"conceito",q:"Que tempo o ます indica?",opts:["Só o passado","Só o presente","Presente ou futuro: não há forma separada para o futuro","Só o futuro"],ans:2,why:"たべます pode ser “como” ou “comerei”. O passado usa ました."},
{id:"b037",topic:"wo",kind:"particula",q:"Complete: パン___ たべます。 (Eu como pão.)",opts:["に","で","か","を"],ans:3,why:"**を** marca o objeto do verbo: aquilo que é comido, bebido ou visto."},
{id:"b038",topic:"wo",kind:"conceito",q:"Qual é a ordem correta de “Eu como pão”?",opts:["パンを たべます。","たべます パンを。","を パン たべます。","たべます を パン。"],ans:0,why:"A ordem é **objeto + を + verbo**, e o verbo fecha a frase. É o contrário do português (“como pão”)."},
{id:"b039",topic:"wo",kind:"leitura",q:"Como a partícula を é lida? Escolha a letra que tem o mesmo som.",opts:["わ","お","ほ","あ"],ans:1,why:"A partícula を lê-se **o**, igual a お. Ela só aparece como partícula."},
{id:"b040",topic:"ni-de",kind:"particula",q:"Complete: がっこう___ べんきょうします。 (Estudo na escola.)",opts:["に","を","で","か"],ans:2,why:"A ação de estudar **acontece** na escola, então se usa **で**. O に marcaria um ponto de chegada."},
{id:"b041",topic:"ni-de",kind:"particula",q:"Complete: バス___ いきます。 (Vou de ônibus.)",opts:["で","に","を","の"],ans:0,why:"**で** também marca o meio usado: バスで (de ônibus)."},
{id:"b042",topic:"ni-de",kind:"particula",q:"Complete: にちようび___ いきます。 (Vou no domingo.)",opts:["で","に","を","へ"],ans:1,why:"Para o dia em que algo acontece, usa-se **に**. O へ marca direção, e o で, lugar ou meio."},
{id:"b043",topic:"aru-iru",kind:"forma",q:"Complete: へやに ねこが ___。 (Há um gato no quarto.)",opts:["あります","ありません","です","います"],ans:3,why:"Para pessoas e animais, usa-se **います**. あります é para coisas e plantas."},
{id:"b044",topic:"aru-iru",kind:"particula",q:"Complete: へや___ ほんが あります。 (Há um livro no quarto.)",opts:["に","で","を","か"],ans:0,why:"O lugar de ある e いる usa **に**, e não で."},
{id:"b045",topic:"aru-iru",kind:"traducao",q:"Como se diz “Eu tenho uma irmã mais nova”?",opts:["わたしは いもうとが あります。","わたしは いもうとを います。","わたしは いもうとが います。","わたしは いもうとです。"],ans:2,why:"“Ter” uma pessoa é “existir para mim”: **いもうとが います**. あります é só para coisas."},
{id:"b046",topic:"ga",kind:"particula",q:"Complete: わたしは コーヒー___ すきです。 (Eu gosto de café.)",opts:["を","が","で","に"],ans:1,why:"Com すき (gostar), a coisa de que se gosta leva **が**, e não を."},
{id:"b047",topic:"ga",kind:"particula",q:"Complete: だれ___ きますか。 (Quem vem?)",opts:["を","に","が","で"],ans:2,why:"Com palavras interrogativas como **だれ**, o sujeito leva が."},
{id:"b048",topic:"ga",kind:"conceito",q:"Qual frase quer dizer “É Tanaka-san quem é estudante” (e não outra pessoa)?",opts:["たなかさんを がくせいです。","たなかさんの がくせいです。","たなかさんは がくせいです。","たなかさんが がくせいです。"],ans:3,why:"**が** destaca quem é o sujeito. たなかさんは fala **sobre** Tanaka-san, sem esse destaque."},
{id:"b049",topic:"he-to",kind:"particula",q:"Complete: ともだち___ いきます。 (Vou com um(a) amigo(a).)",opts:["と","を","の","か"],ans:0,why:"**と** marca a pessoa que faz algo junto com você (“com”)."},
{id:"b050",topic:"he-to",kind:"leitura",q:"Como a partícula へ é lida em にほんへ いきます? Escolha a letra que tem o mesmo som.",opts:["へ","え","お","わ"],ans:1,why:"Como partícula, へ lê-se **e**, igual a え. Dentro de palavras (como へや) continua “he”."},
{id:"b051",topic:"he-to",kind:"particula",q:"Complete: パン___ たまごを たべます。 (Como pão e ovo.)",opts:["に","で","と","の"],ans:2,why:"**と** liga dois substantivos (“e”): パンと たまご."},
{id:"b052",topic:"kara-made",kind:"particula",q:"Complete: くじ___ ごじまで はたらきます。 (Trabalho das nove às cinco.)",opts:["まで","に","で","から"],ans:3,why:"**から** marca o início (das nove) e **まで** marca o fim (até as cinco)."},
{id:"b053",topic:"kara-made",kind:"traducao",q:"O que quer dizer あしたから べんきょうします。",opts:["Vou estudar até amanhã.","Vou estudar a partir de amanhã.","Estudei desde ontem.","Estudo todo dia de manhã."],ans:1,why:"**から** marca o ponto de partida: “a partir de amanhã”. “Até” seria まで."},
{id:"b054",topic:"kara-made",kind:"forma",q:"Como se diz “Como está calor, tomo água”?",opts:["みずを のみますから、あついです。","あついですまで、みずを のみます。","あついですから、みずを のみます。","あついですに、みずを のみます。"],ans:2,why:"O **から** vem depois do **motivo**, e o motivo vem primeiro: あついですから、... A primeira opção inverte causa e consequência."},
{id:"b055",topic:"tai",kind:"forma",q:"Como se diz “Quero comer ramen”?",opts:["ラーメンを たべたいです。","ラーメンを たべますたいです。","ラーメンを たべたいます。","ラーメンを たべるたいです。"],ans:0,why:"Tira-se o ます e acrescenta-se **たい**: たべます → たべたい (+ です)."},
{id:"b056",topic:"tai",kind:"forma",q:"Qual é o negativo de たべたいです (quero comer)?",opts:["たべたいじゃありません","たべたくないです","たべないたいです","たべたいません"],ans:1,why:"O たい funciona como adjetivo い: troca-se o い por **くない** e fica たべたくないです."},
{id:"b057",topic:"tai",kind:"traducao",q:"O que quer dizer たべたかったです?",opts:["Eu não quero comer.","Eu comi.","Vamos comer.","Eu queria comer."],ans:3,why:"Em **たかった**, o たい está no passado: “eu queria comer”."},
{id:"b058",topic:"mashou",kind:"conceito",q:"Qual frase convida alguém, de modo suave, a ir junto?",opts:["いっしょに いきません。","いっしょに いきました。","いっしょに いきませんか。","いっしょに いきたいです。"],ans:2,why:"**～ませんか** é um convite educado (“quer ir junto?”). いきません seria “não vou”, e いきたいです, “eu quero ir”."},
{id:"b059",topic:"mashou",kind:"traducao",q:"O que quer dizer たべましょう。",opts:["Vamos comer.","Eu comi.","Eu não como.","Eu quero comer."],ans:0,why:"**～ましょう** é o “vamos…”: uma sugestão para fazer algo junto."},
{id:"b060",topic:"mashou",kind:"conceito",q:"Alguém diz: いっしょに いきませんか。 Qual resposta ACEITA o convite?",opts:["いいえ、いきません。","ええ、いきましょう。","いいえ、いきたくないです。","すみません、ちょっと…"],ans:1,why:"ええ、いきましょう quer dizer “sim, vamos”. As outras são recusas; すみません、ちょっと… é uma recusa educada que deixa o motivo no ar."},
{id:"b061",topic:"te",kind:"forma",q:"Qual é a forma て de のむ (beber)?",opts:["のんで","のんて","のみて","のって"],ans:0,why:"Os verbos do grupo 1 terminados em む mudam para **んで**: のむ → のんで."},
{id:"b062",topic:"te",kind:"forma",q:"Qual é a forma て de いく (ir)?",opts:["いきて","いいて","いんで","いって"],ans:3,why:"いく é a **exceção**: em vez de いいて, forma-se いって."},
{id:"b063",topic:"te",kind:"conceito",q:"Em たべて、ねました (comi e dormi), qual verbo indica o passado?",opts:["Os dois, たべて e ねました","Só o último, ねました","Só o primeiro, たべて","Nenhum dos dois"],ans:1,why:"A forma て não marca tempo. **Só o último verbo** da frase indica o passado."},
{id:"b064",topic:"te-kudasai",kind:"forma",q:"Como se pede “Espere aqui, por favor”?",opts:["ここで まちます ください。","ここで まつ ください。","ここで まって ください。","ここで まちませんか。"],ans:2,why:"Para pedir uma ação, o verbo vai para a forma **て** + ください: まつ → まって ください. O ませんか seria um convite (“quer esperar aqui?”)."},
{id:"b065",topic:"te-kudasai",kind:"forma",q:"Como se pede uma coisa: “Água, por favor”?",opts:["みずを ください。","みずに ください。","みずで ください。","みずと ください。"],ans:0,why:"Para pedir uma coisa, usa-se **coisa + を + ください**."},
{id:"b066",topic:"te-kudasai",kind:"traducao",q:"O que quer dizer もう いちど いって ください。",opts:["Vou dizer mais uma vez.","Diga mais uma vez, por favor.","Disseram mais uma vez.","Não diga mais."],ans:1,why:"いう → いって + ください é um pedido educado: “diga, por favor”."},
{id:"b067",topic:"te-iru",kind:"forma",q:"Como se diz “Agora estou comendo”?",opts:["いま たべました。","いま たべたいです。","いま たべません。","いま たべて います。"],ans:3,why:"Ação em andamento é **forma て + います**. Com たべます a frase diria “como” ou “vou comer”."},
{id:"b068",topic:"te-iru",kind:"forma",q:"Como se diz “Eu moro em Tóquio”?",opts:["とうきょうに すんで います。","とうきょうに すみます。","とうきょうで すんで います。","とうきょうを すんで います。"],ans:0,why:"“Morar” é um estado que continua: **すんで います**. すみます soa como “vou morar”, e o lugar de すむ leva に."},
{id:"b069",topic:"te-iru",kind:"forma",q:"Alguém pergunta: その ひとを しって いますか。 Como se responde “Não, não conheço”?",opts:["いいえ、しっていません。","いいえ、しりています。","いいえ、しりません。","いいえ、しりませんでした。"],ans:2,why:"O negativo de しっています é **しりません**, e não しっていません."},
{id:"b070",topic:"perguntas",kind:"traducao",q:"O que quer dizer いつ いきますか。",opts:["Onde você vai?","Quando você vai?","Com quem você vai?","Por que você vai?"],ans:1,why:"**いつ** pergunta “quando”. “Onde” é どこ, “quem” é だれ e “por quê” é どうして."},
{id:"b071",topic:"perguntas",kind:"conceito",q:"Qual palavra pergunta “por quê?” e tem resposta terminada em から?",opts:["どう","いつ","だれ","どうして"],ans:3,why:"**どうして** pede um motivo, e a resposta termina em から: にほんが すきですから。"},
{id:"b072",topic:"perguntas",kind:"traducao",q:"Como se pergunta “Como é o Japão?”",opts:["にほんは どうですか。","にほんは なにですか。","にほんは いつですか。","にほんは だれですか。"],ans:0,why:"**どう** pergunta como algo é (opinião ou estado). なに é “o quê”, いつ é “quando”, e だれ é “quem”."},
{id:"b073",topic:"aru-mais",kind:"forma",q:"Complete na forma curta: {お金|かね}が ___。 (Não tenho dinheiro.)",opts:["あらない","ありません","ない","いない"],ans:2,why:"O negativo de ある é uma palavra à parte: **ない**. Não existe あらない. ありません é o negativo educado, e não o curto, e いない é de いる (pessoas e animais)."},
{id:"b074",topic:"aru-mais",kind:"particula",q:"Complete: {教室|きょうしつ}___ {会議|かいぎ}が あります。 (Vai haver uma reunião na sala.)",opts:["に","で","を","の"],ans:1,why:"Para **eventos** (reunião, prova, festa) o lugar leva **で**. O に é para a existência de coisas, como em へやに ほんが あります."},
{id:"b075",topic:"aru-mais",kind:"conceito",q:"O que quer dizer ある{日|ひ}、{山|やま}へ {行|い}きました。?",opts:["Um dia, fui à montanha.","Havia um dia na montanha.","Fui à montanha todos os dias.","Fui à montanha porque tinha tempo."],ans:0,why:"Antes de substantivo, ある quer dizer **“um certo”**: ある{日|ひ} é “um dia”, sem dizer qual. Aqui ele não é o verbo (não leva が e não conjuga), então não significa “haver”."},
// FIM-BASICO
],
intermediario: [
{id:"i001",topic:"ichidan-godan",kind:"conceito",q:"Qual destes verbos é godan?",opts:["{食|た}べる","{見|み}る","{起|お}きる","{帰|かえ}る"],ans:3,why:"{帰|かえ}る parece ichidan (tem え antes do る), mas é uma exceção: é godan. Os outros três são ichidan."},
{id:"i002",topic:"ichidan-godan",kind:"forma",q:"Qual é a forma ない de {買|か}う?",opts:["{買|か}あない","{買|か}わない","{買|か}いない","{買|か}うない"],ans:1,why:"No godan terminado em う, o う vira **わ** na forma ない: {買|か}わない."},
{id:"i003",topic:"ichidan-godan",kind:"forma",q:"Qual é a forma た de {話|はな}す?",opts:["{話|はな}んだ","{話|はな}った","{話|はな}した","{話|はな}いた"],ans:2,why:"Os verbos godan terminados em す formam o て e o た com **し**: {話|はな}す → {話|はな}して, {話|はな}した."},
{id:"i004",topic:"ta",kind:"forma",q:"Como se diz “Ontem estava quente” na forma curta?",opts:["{昨日|きのう}は {暑|あつ}かった。","{昨日|きのう}は {暑|あつ}いだった。","{昨日|きのう}は {暑|あつ}くだった。","{昨日|きのう}は {暑|あつ}かったた。"],ans:0,why:"O passado do adjetivo い está no próprio adjetivo: い → **かった**. Não se junta だった a ele."},
{id:"i005",topic:"ta",kind:"forma",q:"Qual é o passado negativo de {食|た}べる na forma curta (“não comi”)?",opts:["{食|た}べないた","{食|た}べなかった","{食|た}べなくった","{食|た}べませんた"],ans:1,why:"O ない conjuga como adjetivo い: ない → **なかった**. {食|た}べなかった quer dizer “não comi”."},
{id:"i006",topic:"ta",kind:"forma",q:"Qual é a forma た de {行|い}く?",opts:["{行|い}いた","{行|い}んだ","{行|い}った","{行|い}きた"],ans:2,why:"{行|い}く é a exceção: em vez de {行|い}いた, forma-se {行|い}った."},
{id:"i007",topic:"nai",kind:"forma",q:"Qual é a forma ない de {書|か}く?",opts:["{書|か}かない","{書|か}きない","{書|か}くない","{書|か}いない"],ans:0,why:"O godan troca a última sílaba pela da linha **あ**: く → か. Fica {書|か}かない."},
{id:"i008",topic:"nai",kind:"forma",q:"Qual é a forma ない de {来|く}る?",opts:["{来|き}ない","{来|こ}ない","{来|く}ない","{来|く}らない"],ans:1,why:"{来|く}る é irregular: a forma ない é {来|こ}ない."},
{id:"i009",topic:"nai",kind:"forma",q:"Qual é o negativo de ある (“haver, existir” para coisas)?",opts:["あらない","あれない","あくない","ない"],ans:3,why:"O negativo de ある é só **ない**. A forma あらない não existe."},
{id:"i010",topic:"fala-informal",kind:"forma",q:"Como fica “Isto é um livro” na forma curta?",opts:["これは {本|ほん}です。","これは {本|ほん}だ。","これは {本|ほん}じゃありません。","これは {本|ほん}いだ。"],ans:1,why:"Na forma curta, o です vira **だ**. です e じゃありません são da forma educada."},
{id:"i011",topic:"fala-informal",kind:"forma",q:"Como fica “Não gosto de filmes” na forma curta?",opts:["{映画|えいが}は {好|す}きじゃありません。","{映画|えいが}は {好|す}きくない。","{映画|えいが}は {好|す}きじゃない。","{映画|えいが}は {好|す}きだない。"],ans:2,why:"{好|す}き é adjetivo な: o negativo curto é **じゃない**. くない é de adjetivo い, e じゃありません é da forma educada."},
{id:"i012",topic:"fala-informal",kind:"conceito",q:"Quando é natural usar a forma curta?",opts:["Com desconhecidos e clientes","Entre amigos e família, e dentro de frases mais longas","Só em textos muito formais","Sempre que se fala com superiores"],ans:1,why:"A forma curta é íntima: entre amigos e família. Ela também aparece dentro de frases maiores (como ～と{思|おも}う), mesmo em textos educados."},
{id:"i013",topic:"naide-kudasai",kind:"forma",q:"Como se pede “Não corra aqui, por favor”?",opts:["ここで {走|はし}らなくてください。","ここで {走|はし}らないでください。","ここで {走|はし}りません ください。","ここで {走|はし}って ください。"],ans:1,why:"O pedido de **não** fazer algo é forma ない + **でください**. {走|はし}って ください seria o pedido contrário (“corra”)."},
{id:"i014",topic:"naide-kudasai",kind:"traducao",q:"O que quer dizer {忘|わす}れないでください。",opts:["Não se esqueça, por favor.","Por favor, esqueça.","Não consigo esquecer.","Eu não me esqueci."],ans:0,why:"～ないでください é um pedido para **não** fazer algo: “não se esqueça, por favor”."},
{id:"i015",topic:"naide-kudasai",kind:"forma",q:"Como se pede “Não fume aqui, por favor”? (すう = fumar)",opts:["ここで たばこを すいないでください。","ここで たばこを すうないでください。","ここで たばこを すなないでください。","ここで たばこを すわないでください。"],ans:3,why:"すう é godan terminado em う, e o う vira **わ** na forma ない: すわない. Depois vem でください."},
{id:"i016",topic:"temo-ii",kind:"forma",q:"Como se pergunta “Posso me sentar aqui?”",opts:["ここに {座|すわ}ってもいいですか。","ここに {座|すわ}ってはいけません。","ここに {座|すわ}らなければなりませんか。","ここに {座|すわ}らないでください。"],ans:0,why:"Para pedir licença, usa-se forma て + **もいいですか**. As outras opções proíbem, obrigam ou pedem para não sentar."},
{id:"i017",topic:"temo-ii",kind:"traducao",q:"O que quer dizer ここで たばこを すってはいけません。",opts:["Pode fumar aqui.","Não precisa fumar aqui.","Não é permitido fumar aqui.","Por favor, fume aqui."],ans:2,why:"**～てはいけません** proíbe: “não é permitido”. “Não precisa” seria ～なくてもいい."},
{id:"i018",topic:"temo-ii",kind:"conceito",q:"Qual resposta recusa, com jeito, um pedido de licença?",opts:["ええ、どうぞ。","すみません、ちょっと…","いいですよ。","はい、いいです。"],ans:1,why:"すみません、ちょっと… recusa de forma educada, deixando o motivo no ar. As outras três aceitam o pedido."},
{id:"i019",topic:"nakereba",kind:"forma",q:"Como se diz “Preciso fazer a lição”?",opts:["しゅくだいを しなくてもいいです。","しゅくだいを しなければなりません。","しゅくだいを したくありません。","しゅくだいを しないでください。"],ans:1,why:"**～なければなりません** expressa obrigação. しなくてもいいです seria “não precisa”."},
{id:"i020",topic:"nakereba",kind:"forma",q:"Como se diz “Amanhã não preciso ir à escola”?",opts:["{明日|あした}は {学校|がっこう}へ {行|い}かなければなりません。","{明日|あした}は {学校|がっこう}へ {行|い}ってはいけません。","{明日|あした}は {学校|がっこう}へ {行|い}かなくてもいいです。","{明日|あした}は {学校|がっこう}へ {行|い}きたいです。"],ans:2,why:"**～なくてもいい** quer dizer “não precisa”. ～なければならない é obrigação, e ～てはいけません é proibição."},
{id:"i021",topic:"nakereba",kind:"conceito",q:"Qual é a diferença entre ～なくてもいい e ～てはいけません?",opts:["Os dois proíbem algo","Os dois dizem que é preciso fazer","なくてもいい quer dizer “não pode”; ては いけません quer dizer “não precisa”","なくてもいい quer dizer “não precisa”; てはいけません quer dizer “não pode”"],ans:3,why:"**～なくてもいい** é ausência de obrigação (“não precisa”). **～てはいけません** é proibição (“não pode”)."},
{id:"i022",topic:"koto-ga-aru",kind:"forma",q:"Como se diz “Já fui ao Japão”?",opts:["{日本|にほん}へ {行|い}くことが あります。","{日本|にほん}へ {行|い}ったことが あります。","{日本|にほん}へ {行|い}きましたことが あります。","{日本|にほん}へ {行|い}って います。"],ans:1,why:"Experiência é forma **た** + ことがある. Com a forma do dicionário, {行|い}くことがある quer dizer “às vezes vou”."},
{id:"i023",topic:"koto-ga-aru",kind:"traducao",q:"O que quer dizer {寿司|すし}を {食|た}べたことが ありません。",opts:["Nunca comi sushi.","Não vou comer sushi.","Não gosto de sushi.","Não posso comer sushi."],ans:0,why:"～たことが ありません é “nunca fiz ~”: nunca teve essa experiência."},
{id:"i024",topic:"koto-ga-aru",kind:"conceito",q:"Qual é a diferença entre {日本|にほん}へ {行|い}きました e {日本|にほん}へ {行|い}ったことが あります?",opts:["Não há diferença","O primeiro é futuro e o segundo é passado","O primeiro conta que você foi (num momento); o segundo diz que você tem essa experiência","O segundo é negativo"],ans:2,why:"{行|い}きました informa que a viagem aconteceu. {行|い}ったことが あります fala da experiência, sem dizer quando."},
{id:"i025",topic:"to-omou",kind:"forma",q:"Como se diz “Acho que vai chover amanhã”?",opts:["{明日|あした}は {雨|あめ}が {降|ふ}りますと {思|おも}います。","{明日|あした}は {雨|あめ}が {降|ふ}ると {思|おも}います。","{明日|あした}は {雨|あめ}が {降|ふ}るが {思|おも}います。","{明日|あした}は {雨|あめ}を {降|ふ}ると {思|おも}います。"],ans:1,why:"Antes do **と{思|おも}う**, usa-se a forma **curta**: {降|ふ}る. {降|ふ}ります (forma educada) não entra ali."},
{id:"i026",topic:"to-omou",kind:"forma",q:"Como se diz “Acho que Tanaka-san é estudante”?",opts:["{田中|たなか}さんは {学生|がくせい}だと {思|おも}います。","{田中|たなか}さんは {学生|がくせい}ですと {思|おも}います。","{田中|たなか}さんは {学生|がくせい}だを {思|おも}います。","{田中|たなか}さんは {学生|がくせい}のと {思|おも}います。"],ans:0,why:"Com substantivo, a forma curta é **だ**, e ela fica antes do と: {学生|がくせい}だと{思|おも}います."},
{id:"i027",topic:"to-omou",kind:"traducao",q:"O que quer dizer これは {日本語|にほんご}で {何|なん}と {言|い}いますか。",opts:["Quem disse isto em japonês?","Isto é japonês?","Como se diz isto em japonês?","Onde se diz isto em japonês?"],ans:2,why:"Literalmente: “em japonês, isto se diz o quê?”. É a pergunta usada para saber como se diz algo."},
{id:"i028",topic:"mae-ato-toki",kind:"forma",q:"Como se diz “Escovo os dentes antes de dormir”?",opts:["{寝|ね}たまえに、はを みがきます。","{寝|ね}るまえに、はを みがきます。","{寝|ね}てまえに、はを みがきます。","{寝|ね}ますまえに、はを みがきます。"],ans:1,why:"Antes de **まえに**, o verbo fica sempre na forma do dicionário: {寝|ね}るまえに."},
{id:"i029",topic:"mae-ato-toki",kind:"forma",q:"Complete: ___ から、{薬|くすり}を {飲|の}みます. (Tomo o remédio depois de comer.)",opts:["{食|た}べる","{食|た}べて","{食|た}べた","{食|た}べます"],ans:1,why:"“Depois de” com から usa a forma **て**: {食|た}べてから. Com {食|た}べたから, a frase diria “porque comi”."},
{id:"i030",topic:"mae-ato-toki",kind:"forma",q:"Complete: {日本|にほん}へ ___ とき、{寿司|すし}を {食|た}べました. (Quando fui ao Japão, comi sushi.)",opts:["{行|い}く","{行|い}って","{行|い}きます","{行|い}った"],ans:3,why:"Para uma ação já feita, o verbo antes de とき fica na forma **た**: {行|い}ったとき (quando fui). Com {行|い}くとき, a ação ainda não aconteceu."},
{id:"i031",topic:"nagara-tari",kind:"forma",q:"Como se diz “Estudo ouvindo música”?",opts:["{音楽|おんがく}を {聞|き}きながら {勉強|べんきょう}します。","{音楽|おんがく}を {聞|き}いながら {勉強|べんきょう}します。","{音楽|おんがく}を {聞|き}くながら {勉強|べんきょう}します。","{音楽|おんがく}を {聞|き}いたながら {勉強|べんきょう}します。"],ans:0,why:"O **ながら** se liga ao verbo sem ます: {聞|き}きます → {聞|き}き**ながら**."},
{id:"i032",topic:"nagara-tari",kind:"forma",q:"Qual frase lista ações como exemplos (“fiz isto, fiz aquilo, entre outras coisas”)?",opts:["{買|か}い{物|もの}を して、{友達|ともだち}に {会|あ}いました。","{買|か}い{物|もの}を しながら、{友達|ともだち}に {会|あ}いました。","{買|か}い{物|もの}を したり、{友達|ともだち}に {会|あ}ったり しました。","{買|か}い{物|もの}を しなければ、{友達|ともだち}に {会|あ}いました。"],ans:2,why:"**～たり～たりする** lista exemplos de ações. A forma て liga ações em sequência, e ながら indica ações simultâneas."},
{id:"i033",topic:"nagara-tari",kind:"conceito",q:"Em {本|ほん}を {読|よ}んだり、テレビを {見|み}たりします, qual parte recebe o tempo (presente ou passado)?",opts:["Só o する do final","Os dois たり","Só o primeiro たり","Nenhuma parte"],ans:0,why:"Os たり ficam sempre na forma た. Quem marca o tempo é o **する** do final: します (presente) ou しました (passado)."},
{id:"i034",topic:"hikaku",kind:"forma",q:"Como se diz “O trem é mais rápido que o ônibus”?",opts:["バスは {電車|でんしゃ}より {速|はや}いです。","{電車|でんしゃ}は バスより {速|はや}いです。","{電車|でんしゃ}は バスを {速|はや}いです。","{電車|でんしゃ}は バスが {速|はや}いです。"],ans:1,why:"Em **A は B より ~**, A é mais ~ do que B. O より vem depois de quem tem **menos** (o ônibus)."},
{id:"i035",topic:"hikaku",kind:"conceito",q:"Qual pergunta compara DUAS coisas?",opts:["{乗|の}り{物|もの}の なかで、なにが いちばん {速|はや}いですか。","{電車|でんしゃ}は どこが {速|はや}いですか。","{電車|でんしゃ}と バスと、どちらが {速|はや}いですか。","{電車|でんしゃ}は なにを {速|はや}いですか。"],ans:2,why:"**どちらが** compara duas coisas: A と B と、どちらが ~. Para três ou mais, usa-se いちばん."},
{id:"i036",topic:"hikaku",kind:"particula",q:"Complete: {日本|にほん}で {富士山|ふじさん}___ いちばん {高|たか}いです. (No Japão, o Monte Fuji é o mais alto.)",opts:["を","が","に","で"],ans:1,why:"Com **いちばん**, a coisa comparada leva **が**: {富士山|ふじさん}が いちばん {高|たか}い."},
{id:"i037",topic:"joken",kind:"forma",q:"Complete: {時間|じかん}が ___、{電話|でんわ}してください. (Se tiver tempo, me ligue.)",opts:["あると","あったら","あるし","あるのに"],ans:1,why:"Um pedido no final combina com **たら**. O と não aceita pedido no resultado, e のに significa “embora”."},
{id:"i038",topic:"joken",kind:"forma",q:"Qual é a forma ば de {安|やす}い (barato)?",opts:["{安|やす}ければ","{安|やす}いれば","{安|やす}いば","{安|やす}くれば"],ans:0,why:"No adjetivo い, troca-se o い por **ければ**: {安|やす}ければ (se for barato)."},
{id:"i039",topic:"joken",kind:"forma",q:"Qual é a forma ば de {行|い}く?",opts:["{行|い}くば","{行|い}ければ","{行|い}けば","{行|い}きば"],ans:2,why:"No godan, troca-se a última sílaba pela da linha **え** e acrescenta-se ば: く → け, {行|い}けば."},
{id:"i040",topic:"potencial",kind:"forma",q:"Qual é a forma potencial de {食|た}べる?",opts:["{食|た}べける","{食|た}べえる","{食|た}べらる","{食|た}べられる"],ans:3,why:"No ichidan, tira-se o る e acrescenta-se **られる**: {食|た}べられる (conseguir comer)."},
{id:"i041",topic:"potencial",kind:"forma",q:"Qual é a forma potencial de {読|よ}む?",opts:["{読|よ}まれる","{読|よ}みられる","{読|よ}める","{読|よ}もる"],ans:2,why:"No godan, troca-se a última sílaba pela da linha **え** e acrescenta-se る: む → め, {読|よ}める."},
{id:"i042",topic:"potencial",kind:"particula",q:"Complete: {日本語|にほんご}___ {話|はな}せます. (Eu consigo falar japonês.)",opts:["が","に","で","へ"],ans:0,why:"Com a forma potencial, o objeto costuma levar **が**: {日本語|にほんご}が {話|はな}せます."},
{id:"i043",topic:"tsumori",kind:"forma",q:"Como se diz “Pretendo ir ao Japão ano que vem”?",opts:["{来年|らいねん}、{日本|にほん}へ {行|い}ったつもりです。","{来年|らいねん}、{日本|にほん}へ {行|い}きますつもりです。","{来年|らいねん}、{日本|にほん}へ {行|い}くつもりです。","{来年|らいねん}、{日本|にほん}へ {行|い}ってつもりです。"],ans:2,why:"O **つもり** vem depois da forma do dicionário: {行|い}くつもりです. Com a forma た, {行|い}ったつもり quer dizer “achei que tinha ido”."},
{id:"i044",topic:"tsumori",kind:"forma",q:"Qual é a forma volitiva de {寝|ね}る (“vamos dormir”, forma curta)?",opts:["{寝|ね}ろう","{寝|ね}よう","{寝|ね}おう","{寝|ね}らよう"],ans:1,why:"No ichidan, tira-se o る e acrescenta-se **よう**: {寝|ね}る → {寝|ね}よう."},
{id:"i045",topic:"tsumori",kind:"conceito",q:"Qual é a diferença entre ～つもり e ～ようと{思|おも}う?",opts:["つもり é um plano decidido; ようと{思|おも}う é uma intenção mais leve, que pode mudar","つもり é passado; ようと{思|おも}う é futuro","つもり é um pedido; ようと{思|おも}う é uma ordem","Não há diferença nenhuma"],ans:0,why:"O **つもり** mostra um plano já decidido. O **～ようと{思|おも}う** é mais leve: “estou pensando em ~”."},
{id:"i046",topic:"temiru",kind:"traducao",q:"O que quer dizer {日本語|にほんご}で {話|はな}してみました。",opts:["Fui obrigado(a) a falar japonês.","Vi alguém falar japonês.","Deixei alguém falar japonês.","Tentei falar em japonês."],ans:3,why:"**～てみる** quer dizer “tentar, experimentar”. O みる perde o sentido de “ver”."},
{id:"i047",topic:"temiru",kind:"conceito",q:"Em {財布|さいふ}を {忘|わす}れてしまいました, o que o てしまう expressa?",opts:["Preparação para depois","Tentativa","Ação em andamento","Arrependimento: acabei esquecendo"],ans:3,why:"**～てしまう** pode mostrar conclusão ou arrependimento. Aqui é arrependimento: “acabei esquecendo a carteira”."},
{id:"i048",topic:"temiru",kind:"traducao",q:"O que quer dizer {窓|まど}を {開|あ}けておいてください。",opts:["Deixe a janela aberta, por favor.","Abra a janela e saia, por favor.","Experimente abrir a janela.","Não abra a janela, por favor."],ans:0,why:"**～ておく** quer dizer “deixar feito”: {開|あ}けておく é deixar aberto."},
{id:"i049",topic:"sugiru",kind:"forma",q:"Como se diz “Ontem comi demais”?",opts:["{昨日|きのう}は {食|た}べますすぎました。","{昨日|きのう}は {食|た}べすぎました。","{昨日|きのう}は {食|た}べるすぎました。","{昨日|きのう}は {食|た}べてすぎました。"],ans:1,why:"Com verbos, tira-se o **ます** e acrescenta-se すぎる: {食|た}べます → {食|た}べ**すぎ**ます."},
{id:"i050",topic:"sugiru",kind:"forma",q:"Como se diz “Esta bolsa é cara demais”?",opts:["この かばんは {高|たか}いすぎます。","この かばんは {高|たか}すぎます。","この かばんは {高|たか}くすぎます。","この かばんは {高|たか}いなすぎます。"],ans:1,why:"Com adjetivo い, tira-se o **い** antes de すぎる: {高|たか}い → {高|たか}すぎる."},
{id:"i051",topic:"sugiru",kind:"traducao",q:"O que quer dizer この {漢字|かんじ}は {読|よ}みにくいです。",opts:["Este kanji é fácil de ler.","Este kanji tem muitos traços.","Este kanji é difícil de ler.","Não gosto deste kanji."],ans:2,why:"**～にくい** quer dizer “difícil de ~”. O oposto é ～やすい (fácil de ~)."},
{id:"i052",topic:"rentai",kind:"forma",q:"Como se diz “o livro que comprei ontem”?",opts:["{昨日|きのう} {買|か}った {本|ほん}","{昨日|きのう} {買|か}いました {本|ほん}","{本|ほん} {昨日|きのう} {買|か}った","{昨日|きのう} {買|か}って {本|ほん}"],ans:0,why:"A descrição vem **antes** do substantivo e usa a forma curta: {買|か}った {本|ほん}."},
{id:"i053",topic:"rentai",kind:"particula",q:"Complete: {私|わたし}___ {買|か}った {本|ほん} (o livro que eu comprei)",opts:["を","に","と","が"],ans:3,why:"Dentro de uma descrição, o sujeito costuma levar **が**: {私|わたし}が {買|か}った {本|ほん}."},
{id:"i054",topic:"rentai",kind:"conceito",q:"Qual palavra japonesa corresponde ao “que” de “o livro que comprei”?",opts:["と","Nenhuma: a forma curta antes do substantivo já faz esse papel","の","が"],ans:1,why:"O japonês não tem pronome relativo. A forma curta colocada antes do substantivo já faz o papel de “que”."},
{id:"i055",topic:"node-noni",kind:"forma",q:"Complete: ___ ので、ゆっくり {休|やす}みます. (Como é folga, vou descansar à vontade.)",opts:["{休|やす}みだ","{休|やす}みの","{休|やす}みな","{休|やす}みに"],ans:2,why:"Antes de **ので**, o substantivo ganha **な**: {休|やす}みなので. Não existe だので."},
{id:"i056",topic:"node-noni",kind:"forma",q:"Qual frase expressa surpresa ou queixa: “Embora seja domingo, tenho trabalho”?",opts:["{日曜日|にちようび}なので、{仕事|しごと}です。","{日曜日|にちようび}なのに、{仕事|しごと}です。","{日曜日|にちようび}だから、{仕事|しごと}です。","{日曜日|にちようび}で、{仕事|しごと}です。"],ans:1,why:"**のに** quer dizer “embora, apesar de” e mostra surpresa ou queixa. ので e だから dão um motivo."},
{id:"i057",topic:"node-noni",kind:"conceito",q:"Qual destas palavras dá um motivo de forma objetiva e suave (“porque”)?",opts:["のに","ので","けど","が"],ans:1,why:"**ので** dá o motivo de modo suave e objetivo. のに, けど e が expressam contraste."},
{id:"i058",topic:"tame-you",kind:"forma",q:"Complete: {日本語|にほんご}を {勉強|べんきょう}する ___、{日本|にほん}へ {行|い}きます. (Vou ao Japão para estudar japonês.)",opts:["ために","ように","ので","のに"],ans:0,why:"A finalidade de uma ação que você controla, com o mesmo sujeito, usa **ために**."},
{id:"i059",topic:"tame-you",kind:"forma",q:"Complete: {日本語|にほんご}が {話|はな}せる ___、{毎日|まいにち} {練習|れんしゅう}します. (Pratico todo dia para conseguir falar japonês.)",opts:["ために","ように","ので","のに"],ans:1,why:"Com a forma potencial (“conseguir falar”), a finalidade usa **ように**."},
{id:"i060",topic:"tame-you",kind:"forma",q:"Como se diz “Trabalho pela minha família”?",opts:["{家族|かぞく}ために、{働|はたら}いて います。","{家族|かぞく}の ために、{働|はたら}いて います。","{家族|かぞく}に ために、{働|はたら}いて います。","{家族|かぞく}が ために、{働|はたら}いて います。"],ans:1,why:"Com substantivo, usa-se **の + ために**: {家族|かぞく}の ために."},
{id:"i061",topic:"ageru",kind:"forma",q:"“Um(a) amigo(a) me deu um presente.” Qual verbo completa a frase? {友達|ともだち}は {私|わたし}に プレゼントを ___。",opts:["あげました","くれました","もらいました","さしあげました"],ans:1,why:"Quando alguém dá algo **para mim**, usa-se **くれる**. あげる é para dar a outra pessoa."},
{id:"i062",topic:"ageru",kind:"particula",q:"Complete: {私|わたし}は {友達|ともだち}___ プレゼントを もらいました. (Recebi um presente de um(a) amigo(a).)",opts:["を","が","で","に"],ans:3,why:"Em **もらう**, quem dá leva **に** (ou から): {友達|ともだち}に もらいました."},
{id:"i063",topic:"ageru",kind:"conceito",q:"Qual frase quer dizer “Emprestei um livro a um(a) amigo(a)” (fiz algo por alguém)?",opts:["{友達|ともだち}に {本|ほん}を {貸|か}して あげました。","{友達|ともだち}に {本|ほん}を {貸|か}して もらいました。","{友達|ともだち}に {本|ほん}を {貸|か}して くれました。","{友達|ともだち}に {本|ほん}を {貸|か}して みました。"],ans:0,why:"**～てあげる** é fazer algo por alguém. ～てもらう e ～てくれる são as ações que os outros fazem por você."},
{id:"i064",topic:"souda",kind:"forma",q:"Qual é a forma de “parece gostoso” (aparência) a partir de おいしい?",opts:["おいしいそう","おいしくそう","おいしそう","おいしだそう"],ans:2,why:"Para aparência, tira-se o **い** do adjetivo い: おいしい → おいし**そう**."},
{id:"i065",topic:"souda",kind:"conceito",q:"Em ニュースに よると、{明日|あした}は {雨|あめ}が {降|ふ}る そうです, o そうです indica...",opts:["Aparência visual","Que a informação foi ouvida de outra fonte","Um pedido","Uma vontade"],ans:1,why:"Forma curta + そうです quer dizer “dizem que ~”: informação de segunda mão."},
{id:"i066",topic:"souda",kind:"forma",q:"Como se diz “Este problema parece difícil” (aparência)?",opts:["この {問題|もんだい}は {難|むずか}しいそうです。","この {問題|もんだい}は {難|むずか}しそうです。","この {問題|もんだい}は {難|むずか}しくそうです。","この {問題|もんだい}は {難|むずか}しだそうです。"],ans:1,why:"Aparência: tira-se o い e acrescenta-se そう. {難|むずか}しいそうです (forma curta + そうです) quer dizer “dizem que é difícil”."},
{id:"i067",topic:"dake-shika",kind:"forma",q:"Qual frase está correta para “Não bebi nada além de água”?",opts:["{水|みず}しか {飲|の}みました。","{水|みず}しか {飲|の}みませんでした。","{水|みず}だけ {飲|の}みませんでした。","{水|みず}ばかり {飲|の}みませんでした。"],ans:1,why:"**しか** exige o verbo no **negativo**: {水|みず}しか {飲|の}みませんでした."},
{id:"i068",topic:"dake-shika",kind:"conceito",q:"Complete: {教室|きょうしつ}には ___ いません. (Não há ninguém na sala de aula.)",opts:["だれでも","だれが","だれも","だれと"],ans:2,why:"**だれも + negativo** quer dizer “ninguém”. だれでも é “qualquer pessoa”."},
{id:"i069",topic:"dake-shika",kind:"forma",q:"Como se sugere “Que tal um chá ou algo assim?”",opts:["{お茶|おちゃ}しか {飲|の}みませんか。","{お茶|おちゃ}でも {飲|の}みませんか。","{お茶|おちゃ}ばかり {飲|の}みませんか。","{お茶|おちゃ}を {飲|の}みませんでした。"],ans:1,why:"**でも** dá uma sugestão suave (“~ ou algo assim”). しか exige verbo negativo, e ばかり quer dizer “só”."},
{id:"i070",topic:"adv-naru",kind:"forma",q:"Complete: ここでは ___ {話|はな}してください. (Fale baixinho aqui.)",opts:["しずか","しずかな","しずかく","しずかに"],ans:3,why:"O adjetivo な vira advérbio com **に**: しずかに. O く é do adjetivo い."},
{id:"i071",topic:"adv-naru",kind:"forma",q:"Como se diz “Ultimamente esfriou”?",opts:["{最近|さいきん}、{寒|さむ}に なりました。","{最近|さいきん}、{寒|さむ}く なりました。","{最近|さいきん}、{寒|さむ}い なりました。","{最近|さいきん}、{寒|さむ}さ なりました。"],ans:1,why:"“Ficar ~” com adjetivo い é **く + なる**: {寒|さむ}く なる."},
{id:"i072",topic:"adv-naru",kind:"forma",q:"Qual frase quer dizer “É melhor não ir”?",opts:["{行|い}く ほうが いいです。","{行|い}かなく ほうが いいです。","{行|い}かなくて ほうが いいです。","{行|い}かない ほうが いいです。"],ans:3,why:"Para aconselhar a **não** fazer algo, usa-se a forma **ない** + ほうがいい."},
{id:"i073",topic:"koto-no",kind:"forma",q:"Como se diz “Gosto de cozinhar”?",opts:["{料理|りょうり}を します のが {好|す}きです。","{料理|りょうり}を する のが {好|す}きです。","{料理|りょうり}を して のが {好|す}きです。","{料理|りょうり}を しますが {好|す}きです。"],ans:1,why:"Antes de **の** (o ato de ~), o verbo fica na forma curta: する のが {好|す}き."},
{id:"i074",topic:"koto-no",kind:"conceito",q:"Qual destas expressões usa sempre こと (e não の)?",opts:["～のが すき","～のを {見|み}る","～たことが ある","～のが じょうず"],ans:2,why:"**～たことが ある** (experiência) e ～ことが できる usam sempre こと. Com すき, じょうず e ver ou ouvir, o の é o mais natural."},
{id:"i075",topic:"koto-no",kind:"conceito",q:"Em {私|わたし}の {趣味|しゅみ}は {映画|えいが}を {見|み}る ことです, o que o こと faz?",opts:["Marca o objeto do verbo","Transforma a frase em substantivo: o ato de assistir a filmes","Indica uma experiência passada","Transforma a frase em pergunta"],ans:1,why:"**こと** transforma a frase em substantivo: “o ato de ~”. Por isso ela pode ser o assunto de です."},
{id:"i076",topic:"setsuzoku",kind:"conceito",q:"Qual conjunção quer dizer “mas”?",opts:["そして","でも","だから","それに"],ans:1,why:"**でも** (e しかし, mais formal) quer dizer “mas”. そして soma, だから dá consequência, e それに quer dizer “além disso”."},
{id:"i077",topic:"setsuzoku",kind:"conceito",q:"Qual conjunção quer dizer “por isso” (consequência)?",opts:["でも","そして","ところで","だから"],ans:3,why:"**だから** (ou ですから, mais educado) liga uma consequência: “por isso”."},
{id:"i078",topic:"setsuzoku",kind:"conceito",q:"Qual conjunção se usa para mudar de assunto (“a propósito”)?",opts:["それに","だから","ところで","でも"],ans:2,why:"**ところで** muda de assunto: “a propósito”."},
{id:"i079",topic:"hesitacoes-expressoes",kind:"conceito",q:"Qual é a diferença entre **ええ** e **うん** ao dizer “sim”?",opts:["Os dois têm a mesma formalidade","**ええ** é educado; **うん** é informal, para amigos e família","**うん** é mais educado que **ええ**","**ええ** só se usa por escrito"],ans:1,why:"**ええ** é o “sim” educado e **うん** é o informal. Com superiores, o mais seguro é **はい**."},
{id:"i080",topic:"hesitacoes-expressoes",kind:"conceito",q:"Em qual frase o **あの** é hesitação (“ahn…”), e não “aquele”?",opts:["あの{人|ひと}は {先生|せんせい}です。","あの、すみません。","あの {山|やま}は {高|たか}いです。","あの {本|ほん}は わたしのです。"],ans:1,why:"Em **あの、すみません**, o あの vem seguido de vírgula e serve para chamar a atenção. Nas outras, あの + substantivo quer dizer **“aquele”**: あの{人|ひと} (aquela pessoa), あの{山|やま} (aquela montanha)."},
{id:"i081",topic:"hesitacoes-expressoes",kind:"conceito",q:"Quando se diz **お{疲|つか}れ{様|さま}でした**?",opts:["Ao chegar ao trabalho de manhã","Ao fim do trabalho, aos colegas","Ao pedir desculpas a um cliente","Ao conhecer alguém pela primeira vez"],ans:1,why:"**お{疲|つか}れ{様|さま}でした** é a frase de trabalho para o fim do dia (“obrigado pelo esforço”). Durante o dia se diz お{疲|つか}れ{様|さま}です. Para desculpas, use ごめんなさい ou すみません; para se apresentar, よろしく お{願|ねが}いします."},
// FIM-INTERMEDIARIO
],
avancado: [
{id:"a001",topic:"passivo",kind:"forma",q:"Qual é o passivo de {買|か}う?",opts:["{買|か}あれる","{買|か}かれる","{買|か}われる","{買|か}られる"],ans:2,why:"Nos verbos em う, o う vira **わ** antes de れる: {買|か}う → {買|か}われる, e não あ."},
{id:"a002",topic:"passivo",kind:"particula",q:"Complete: {私|わたし}は {先生|せんせい}（　）ほめられました。",opts:["を","に","で","へ"],ans:1,why:"No passivo, quem faz a ação leva **に**: {先生|せんせい}に ほめられました (fui elogiado(a) pelo(a) professor(a))."},
{id:"a003",topic:"passivo",kind:"forma",q:"Qual é o passivo de {来|く}る?",opts:["{来|こ}られる","{来|き}られる","{来|く}られる","{来|こ}させる"],ans:0,why:"O くる vira **こられる** no passivo, e não きられる. {来|こ}させる é o causativo."},
{id:"a004",topic:"causativo",kind:"forma",q:"Qual é o causativo de {食|た}べる?",opts:["{食|た}べられる","{食|た}べせる","{食|た}べらせる","{食|た}べさせる"],ans:3,why:"Nos verbos ichidan, tira-se る e acrescenta-se **させる**: {食|た}べる → {食|た}べさせる. {食|た}べられる é o passivo (ou o potencial)."},
{id:"a005",topic:"causativo",kind:"particula",q:"Complete: {母|はは}は {子|こ}ども（　）{野菜|やさい}を {食|た}べさせました。",opts:["を","に","が","で"],ans:1,why:"Como o verbo já tem o objeto {野菜|やさい}を, quem recebe a ordem leva **に**: {子|こ}どもに {野菜|やさい}を {食|た}べさせる."},
{id:"a006",topic:"causativo",kind:"conceito",q:"O que quer dizer ～**させて ください**?",opts:["“Deixe-me fazer”: eu faço, com a sua permissão","“Faça, por favor”: você faz","“Fui obrigado(a) a fazer”","“Quero que você faça”"],ans:0,why:"～させて ください é um pedido de permissão: **eu** faço. ～して ください é o pedido para que **você** faça."},
{id:"a007",topic:"causativo-passivo",kind:"forma",q:"Qual é a forma curta de {書|か}かせられる?",opts:["{書|か}かせれる","{書|か}かされる","{書|か}かさせる","{書|か}かれされる"],ans:1,why:"Nos verbos godan, ～せられる vira **～される**: {書|か}かせられる → {書|か}かされる. A exceção são os verbos em す."},
{id:"a008",topic:"causativo-passivo",kind:"forma",q:"Qual é o causativo-passivo de する?",opts:["されられる","しさせる","させられる","させれる"],ans:2,why:"O する forma o causativo-passivo com **させられる**: する → させる → させられる."},
{id:"a009",topic:"causativo-passivo",kind:"traducao",q:"O que quer dizer {昨日|きのう}は {残業|ざんぎょう}を させられました。?",opts:["Ontem fiz hora extra de bom grado","Ontem obriguei alguém a fazer hora extra","Ontem deixei alguém fazer hora extra","Ontem fui obrigado(a) a fazer hora extra"],ans:3,why:"O causativo-passivo mostra que a pessoa foi obrigada a fazer algo contra a vontade: “fui obrigado(a) a fazer hora extra”."},
{id:"a010",topic:"you-ni-suru",kind:"conceito",q:"Qual frase quer dizer “Passei a conseguir nadar”?",opts:["{泳|およ}ぐ ことに しました","{泳|およ}ぎ たく なりました","{泳|およ}げる ように なりました","{泳|およ}げる ことに なりました"],ans:2,why:"Com o potencial, ～ように なる é o jeito natural de dizer “passei a conseguir ~”. ～ことに しました é “decidi”."},
{id:"a011",topic:"you-ni-suru",kind:"conceito",q:"Qual frase quer dizer “Procuro não chegar atrasado(a)” (esforço)?",opts:["{遅刻|ちこく}しない ように して います","{遅刻|ちこく}する ように して います","{遅刻|ちこく}しない ことに なりました","{遅刻|ちこく}した ところです"],ans:0,why:"**ように する** é esforço: {遅刻|ちこく}しない ように します. ことに なりました diria que “ficou decidido”."},
{id:"a012",topic:"you-ni-suru",kind:"traducao",q:"O que quer dizer {目|め}が {悪|わる}く なって、{字|じ}が 読めなく なりました。?",opts:["A vista melhorou e passei a conseguir ler as letras","A vista piorou e deixei de conseguir ler as letras","Decidi não ler as letras porque a vista piorou","Procuro não ler as letras porque a vista é ruim"],ans:1,why:"～**なく なる** quer dizer “deixar de ~”: {読|よ}めなく なりました = deixei de conseguir ler."},
{id:"a013",topic:"koto-ni-suru",kind:"conceito",q:"Qual é a diferença entre ～ことに **しました** e ～ことに **なりました**?",opts:["しました é passado e なりました é futuro","Os dois são iguais; só muda a polidez","なりました: eu decidi; しました: ficou decidido por outros","しました: eu decidi; なりました: ficou decidido (por outros ou pelas circunstâncias)"],ans:3,why:"**する** = você decide; **なる** = “ficou decidido”, por outros ou pelas circunstâncias. Por isso ことに なりました também soa mais discreto."},
{id:"a014",topic:"koto-ni-suru",kind:"traducao",q:"O que quer dizer {来月|らいげつ}、{大阪|おおさか}へ {転勤|てんきん}する ことに なりました。?",opts:["Decidi pedir transferência para Osaka no mês que vem","Estou me esforçando para ser transferido(a) para Osaka","Ficou decidido que serei transferido(a) para Osaka no mês que vem","Fui a Osaka a trabalho no mês passado"],ans:2,why:"～ことに なりました diz que algo **ficou decidido**, em geral por outros ou pela empresa: serei transferido(a) para Osaka."},
{id:"a015",topic:"koto-ni-suru",kind:"forma",q:"Como se diz “Decidi não comer”?",opts:["{食|た}べる ことに しませんでした","{食|た}べない ことに しました","{食|た}べない ように しました","{食|た}べない ことに なりました"],ans:1,why:"O ない vem **antes** de ことに する: {食|た}べない ことに しました. ことに しませんでした diria “não decidi comer”."},
{id:"a016",topic:"to-ii",kind:"conceito",q:"Qual frase expressa esperança: “Tomara que amanhã faça sol”?",opts:["{明日|あした}は {晴|は}れると いいですね","{明日|あした}は {晴|は}れれば よかったですね","{明日|あした}は {晴|は}れなければ いいですね","{明日|あした}は {晴|は}れる ことに しました"],ans:0,why:"**と いい** é o mais natural para esperança no futuro. ば よかった é lamento sobre o passado."},
{id:"a017",topic:"to-ii",kind:"forma",q:"Como se diz “Eu devia ter dito” (lamento)?",opts:["{言|い}えば いい","{言|い}った ほうが いい","{言|い}えば よかった","{言|い}わない ことに した"],ans:2,why:"**～ば よかった** é o lamento sobre o passado: {言|い}えば よかった = devia ter dito (e não disse)."},
{id:"a018",topic:"to-ii",kind:"conceito",q:"Qual frase quer dizer “É só pegar o ônibus”?",opts:["バスに {乗|の}った ほうが いいです","バスに {乗|の}らなければ いいです","バスに {乗|の}った ことが あります","バスに {乗|の}れば いいです"],ans:3,why:"～**ば いい** quer dizer “é só ~”. ～ほうが いい compara opções (“é melhor ~”)."},
{id:"a019",topic:"ba-hodo",kind:"forma",q:"Complete: {練習|れんしゅう}（　） する ほど、うまく なります。",opts:["したら","すると","すれば","しても"],ans:2,why:"A estrutura é verbo na forma **ば** + dicionário + ほど: {練習|れんしゅう}すれば する ほど (quanto mais se treina)."},
{id:"a020",topic:"ba-hodo",kind:"forma",q:"Qual é a forma correta de “quanto mais calmo, melhor”?",opts:["{静|しず}かなら {静|しず}かなほど いいです","{静|しず}かければ {静|しず}かなほど いいです","{静|しず}かなら {静|しず}かいほど いいです","{静|しず}かなば {静|しず}かなほど いいです"],ans:0,why:"Com adjetivo な, a primeira parte usa **なら** e a segunda repete o adjetivo com な: {静|しず}かなら {静|しず}かな ほど."},
{id:"a021",topic:"ba-hodo",kind:"forma",q:"Qual é a forma correta de “quanto melhor, melhor” com いい?",opts:["いいば いいほど","いければ いいほど","よいなら いいほど","よければ いいほど"],ans:3,why:"O adjetivo **いい** vira **よければ** na primeira parte: よければ いいほど."},
{id:"a022",topic:"wake",kind:"conceito",q:"Qual é a ideia de ～**わけだ**?",opts:["“Talvez”: uma possibilidade","“Então é por isso”: conclusão natural a partir de algo que acabou de saber","“Não posso”: uma proibição","“Quero”: um desejo"],ans:1,why:"**わけだ** diz “agora entendo por que”, tirando uma conclusão natural do que se acabou de saber."},
{id:"a023",topic:"wake",kind:"traducao",q:"O que quer dizer {日本語|にほんご}が {嫌|きら}いな わけでは ありません。?",opts:["Eu detesto japonês","Com certeza não gosto de japonês","Não posso gostar de japonês","Não é que eu não goste de japonês"],ans:3,why:"**わけでは ない** nega só em parte: “não é que ~”. Para negar de vez, usa-se a negação simples."},
{id:"a024",topic:"wake",kind:"forma",q:"Qual frase quer dizer “Não posso deixar de ir”?",opts:["{行|い}く わけには いきません","{行|い}かない わけには いきません","{行|い}かない わけが ありません","{行|い}かない わけでは ありません"],ans:1,why:"**～ない わけには いかない** quer dizer “não posso deixar de ~”. {行|い}く わけには いかない diria “não posso ir”."},
{id:"a025",topic:"hazu",kind:"conceito",q:"Qual é a diferença entre ～はずが ない e ～ない はずだ?",opts:["Os dois querem dizer “não pode ser”","はずが ない: “o esperado é que não ~”; ない はずだ: “não pode ser”","はずが ない: “não pode ser”; ない はずだ: “o esperado é que não ~”","はずが ない é passado; ない はずだ é futuro"],ans:2,why:"**はずが ない** é “não pode ser”. **～ない はずだ** é só “o esperado é que não aconteça”."},
{id:"a026",topic:"hazu",kind:"particula",q:"Complete: {山田|やまだ}さんは {日本人|にほんじん}（　）はずです。",opts:["だ","の","な","に"],ans:1,why:"Com substantivo, o はず liga com **の**: {日本人|にほんじん}の はず. Com adjetivo な, liga com な."},
{id:"a027",topic:"hazu",kind:"conceito",q:"Qual frase diz “A reunião deve começar às três” com base no horário marcado?",opts:["{会議|かいぎ}は 三時に {始|はじ}まる べきです","{会議|かいぎ}は 三時に {始|はじ}まる ところです","{会議|かいぎ}は 三時に {始|はじ}まる わけには いきません","{会議|かいぎ}は 三時に {始|はじ}まる はずです"],ans:3,why:"**はず** é dedução com base em algo objetivo, como o horário. べき é obrigação moral e ところ é “prestes a”."},
{id:"a028",topic:"kamoshirenai",kind:"forma",q:"Complete: あしたは {雨|あめ}（　）かも しれません。",opts:["だ","な","の","nada (sem だ nem な)"],ans:3,why:"Substantivo e adjetivo な entram **sem だ e sem な** antes de かも しれない: {雨|あめ} かも しれません."},
{id:"a029",topic:"kamoshirenai",kind:"conceito",q:"Qual é o grau de certeza de ～かも しれない?",opts:["É só uma possibilidade, sem certeza","Quase certeza, com base em indícios","Certeza absoluta","Dedução baseada em regra ou horário"],ans:0,why:"**かも しれない** só diz que é **possível**, e não que é certo. Para quase certeza, use ～に ちがいない."},
{id:"a030",topic:"kamoshirenai",kind:"forma",q:"Como se diz “Talvez ele não venha”?",opts:["{来|き}ない かも しれません","{来|こ}なかった かも しれません","{来|こ}ない かも しれません","{来|こ}ないだ かも しれません"],ans:2,why:"O negativo segue a forma curta: {来|こ}ない かも しれません. {来|こ}なかった seria “talvez não tenha vindo”."},
{id:"a031",topic:"ni-chigainai",kind:"conceito",q:"{電気|でんき}が ついて いるから、{家|いえ}に {誰|だれ}か いる（　）。 Qual expressão dá o sentido “com certeza”?",opts:["かも しれない","に ちがいない","わけが ない","ことに した"],ans:1,why:"**に ちがいない** é uma conclusão quase certa a partir de indícios (a luz acesa). かも しれない só diz “talvez”."},
{id:"a032",topic:"ni-chigainai",kind:"forma",q:"Qual é a forma correta de “Com certeza é genuíno”?",opts:["{本物|ほんもの}だ に ちがいない","{本物|ほんもの}な に ちがいない","{本物|ほんもの}の に ちがいない","{本物|ほんもの}に ちがいない"],ans:3,why:"Como em かも しれない, substantivo entra **sem だ e sem な**: {本物|ほんもの}に ちがいない."},
{id:"a033",topic:"ni-chigainai",kind:"conceito",q:"O que diferencia ～に ちがいない de ～はずだ?",opts:["はず se apoia em algo objetivo (horário, regra, lógica); に ちがいない é uma convicção pessoal","に ちがいない é mais educado que はず","São sempre trocáveis, sem diferença","はず só serve para o passado"],ans:0,why:"**はず** se apoia em algo objetivo. **に ちがいない** mostra a sua convicção pessoal, muitas vezes por intuição."},
{id:"a034",topic:"seide-okagede",kind:"conceito",q:"Complete: あなたの（　）、{試験|しけん}に {合格|ごうかく}できました。",opts:["せいで","ところで","おかげで","ばかりで"],ans:2,why:"**おかげで** dá a causa de algo bom (“graças a você”). **せいで** é para algo ruim."},
{id:"a035",topic:"seide-okagede",kind:"forma",q:"Qual frase está correta?",opts:["{雨|あめ}の せいで {遅|おく}れました","{雨|あめ} せいで {遅|おく}れました","{雨|あめ}な せいで {遅|おく}れました","{雨|あめ}だ せいで {遅|おく}れました"],ans:0,why:"**せい** é um substantivo: com outro substantivo, liga com **の**: {雨|あめ}の せいで."},
{id:"a036",topic:"seide-okagede",kind:"traducao",q:"O que quer dizer あなたの おかげで {失敗|しっぱい}しました。?",opts:["Graças a você, tudo deu certo","Graças a você (em tom sarcástico), deu errado","Fracassei por minha própria culpa","Você fracassou por minha culpa"],ans:1,why:"**おかげで** com um resultado ruim é sarcasmo: “graças a você”, com ironia. Use com cuidado."},
{id:"a037",topic:"nagaramo-tsutsu",kind:"forma",q:"Qual forma está correta para “Embora soubesse ~”?",opts:["{知|し}りながらも","{知|し}って ながらも","{知|し}った ながらも","{知|し}る ながらも"],ans:0,why:"O verbo fica na forma **ます sem ます**: {知|し}り + ながらも. Não se usa a forma て nem o passado."},
{id:"a038",topic:"nagaramo-tsutsu",kind:"conceito",q:"Qual é a diferença entre ～**ながら** e ～**ながらも**?",opts:["Os dois querem dizer “ao mesmo tempo”","ながら: ao mesmo tempo ({歩|ある}きながら {話|はな}す); ながらも: embora (contraste)","ながら: embora; ながらも: ao mesmo tempo","ながらも é só a forma educada de ながら"],ans:1,why:"**ながら** é “ao mesmo tempo”. **ながらも** traz contraste: “embora ~”."},
{id:"a039",topic:"nagaramo-tsutsu",kind:"conceito",q:"Qual condição vale para ～ながらも?",opts:["Os sujeitos das duas partes devem ser diferentes","O verbo antes deve estar no passado","A segunda parte deve ser um pedido","O sujeito das duas partes é o mesmo"],ans:3,why:"As duas partes têm o **mesmo sujeito**. Com sujeitos diferentes, usa-se ～が, ～けれど ou ～のに."},
{id:"a040",topic:"tokoro-bakari",kind:"conceito",q:"Qual frase quer dizer “Estou prestes a sair de casa”?",opts:["これから {家|いえ}を {出|で}た ところです","これから {家|いえ}を {出|で}た ばかりです","これから {家|いえ}を {出|で}て いる ところです","これから {家|いえ}を {出|で}る ところです"],ans:3,why:"**Dicionário + ところ** é “prestes a ~”. {出|で}た ところ é “acabei de sair”."},
{id:"a041",topic:"tokoro-bakari",kind:"conceito",q:"Complete: {先月|せんげつ} {結婚|けっこん}した（　）です。 (“Casei há pouco, no mês passado”)",opts:["ばかり","ところ","わけ","はず"],ans:0,why:"**ばかり** é a sensação de “faz pouco tempo” e pode ser de um mês. ところ pede um momento de minutos."},
{id:"a042",topic:"tokoro-bakari",kind:"conceito",q:"Qual frase quer dizer “Agora estou no meio do jantar”?",opts:["いま {晩|ばん}ごはんを {食|た}べる ところです","いま {晩|ばん}ごはんを {食|た}べた ところです","いま {晩|ばん}ごはんを {食|た}べて いる ところです","いま {晩|ばん}ごはんを {食|た}べて いる はずです"],ans:2,why:"**～て いる ところ** é “neste exato momento”, no meio da ação. {食|た}べる ところ é “prestes a comer”."},
{id:"a043",topic:"temo-demo",kind:"forma",q:"Qual frase quer dizer “Mesmo que chova, o jogo vai acontecer”?",opts:["{雨|あめ}が {降|ふ}ったら、{試合|しあい}は あります","{雨|あめ}が {降|ふ}っても、{試合|しあい}は あります","{雨|あめ}が {降|ふ}れば、{試合|しあい}は あります","{雨|あめ}が {降|ふ}ってから、{試合|しあい}は あります"],ans:1,why:"**～ても** é “mesmo que”: o resultado não muda. ～たら e ～ば são “se”, e ～てから é “depois de”."},
{id:"a044",topic:"temo-demo",kind:"conceito",q:"Complete: （　）{食|た}べても、{太|ふと}りません。",opts:["いくら","もし","たぶん","まだ"],ans:0,why:"**いくら** (ou たとえ) no começo reforça o ～ても: “por mais que eu coma, não engordo”."},
{id:"a045",topic:"temo-demo",kind:"conceito",q:"A forma ～ても é a mesma em ～ても いい (“pode”) e em ～ても (“mesmo que”). O que decide o sentido?",opts:["A polidez da frase","A partícula antes do verbo","O final da frase","O tempo do verbo antes"],ans:2,why:"A forma é igual; o **final da frase** decide: ～ても いい é “pode ~”, e ～ても com outro resultado é “mesmo que ~”."},
{id:"a046",topic:"toshite-nitsuite",kind:"particula",q:"Complete: {日本|にほん}の {文化|ぶんか}（　）{調|しら}べて います。 (“Estou pesquisando sobre a cultura”)",opts:["として","において","に{対|たい}して","について"],ans:3,why:"**について** marca o assunto: “sobre ~”. として é papel, において é lugar formal e に{対|たい}して é alvo ou contraste."},
{id:"a047",topic:"toshite-nitsuite",kind:"forma",q:"Qual é a forma correta de “livro sobre o Japão”?",opts:["{日本|にほん}にとって {本|ほん}","{日本|にほん}についた {本|ほん}","{日本|にほん}についての {本|ほん}","{日本|にほん}について {本|ほん}"],ans:2,why:"Para ligar a outro substantivo, **について** vira **についての**: {日本|にほん}についての {本|ほん}."},
{id:"a048",topic:"toshite-nitsuite",kind:"conceito",q:"Complete: {私|わたし}は {留学生|りゅうがくせい}（　）{日本|にほん}に {来|き}ました。 (“como estudante de intercâmbio”)",opts:["について","として","において","に{対|たい}して"],ans:1,why:"**として** marca o papel ou a posição: “como ~”. {留学生|りゅうがくせい}として = na condição de estudante de intercâmbio."},
{id:"a049",topic:"ni-yotte",kind:"traducao",q:"O que quer dizer {国|くに}によって {習慣|しゅうかん}が {違|ちが}います。?",opts:["Os costumes são os mesmos em todos os países","Os costumes foram criados pelo país","Os costumes variam de país para país","Fui ao país para aprender os costumes"],ans:2,why:"Com verbos como {違|ちが}う e {変|か}わる, **によって** é “depende de”: os costumes variam conforme o país."},
{id:"a050",topic:"ni-yotte",kind:"forma",q:"Qual é a forma correta de “atraso causado por acidente”?",opts:["{事故|じこ}による {遅|おく}れ","{事故|じこ}によって {遅|おく}れ","{事故|じこ}によっての {遅|おく}れ","{事故|じこ}によるの {遅|おく}れ"],ans:0,why:"Para ligar a um substantivo, usa-se **による**: {事故|じこ}による {遅|おく}れ."},
{id:"a051",topic:"ni-yotte",kind:"conceito",q:"Como se diz “cortar com uma faca” (ferramenta concreta)?",opts:["ナイフによって {切|き}る","ナイフについて {切|き}る","ナイフで {切|き}る","ナイフとして {切|き}る"],ans:2,why:"Para uma ferramenta concreta, usa-se **で**: ナイフで {切|き}る. Não serve によって."},
{id:"a052",topic:"zaru-wo-enai",kind:"forma",q:"Qual é a forma correta de “Não tenho como deixar de ir”?",opts:["{行|い}かないを{得|え}ません","{行|い}きざるを{得|え}ません","{行|い}けざるを{得|え}ません","{行|い}かざるを{得|え}ません"],ans:3,why:"A base é a forma ない **sem ない** + ざるを{得|え}ない: {行|い}かない → {行|い}かざるを{得|え}ない."},
{id:"a053",topic:"zaru-wo-enai",kind:"forma",q:"Qual é a forma de する antes de ～ざるを{得|え}ない?",opts:["せざるを{得|え}ない","しざるを{得|え}ない","さざるを{得|え}ない","すざるを{得|え}ない"],ans:0,why:"**する** vira **せざるを{得|え}ない** (não しざる). É a exceção que mais gera erro."},
{id:"a054",topic:"zaru-wo-enai",kind:"conceito",q:"O que expressa ～ざるを{得|え}ない?",opts:["Capacidade: consigo fazer","Desejo forte de fazer","Permissão para fazer","Falta de escolha: tenho que fazer, contra a vontade"],ans:3,why:"**ざるを{得|え}ない** diz que não há outra saída. Não é capacidade nem vontade."},
{id:"a055",topic:"zu-ni",kind:"forma",q:"Como se diz “sem estudar” com ～ずに?",opts:["{勉強|べんきょう}せずに","{勉強|べんきょう}しずに","{勉強|べんきょう}さずに","{勉強|べんきょう}すずに"],ans:0,why:"**する → せずに** (não しずに). É a exceção da forma ずに."},
{id:"a056",topic:"zu-ni",kind:"forma",q:"Qual é a forma de {言|い}う antes de ずに (“sem dizer”)?",opts:["{言|い}あずに","{言|い}いずに","{言|い}わずに","{言|い}うずに"],ans:2,why:"Nos verbos em う, o う vira **わ**: {言|い}わずに."},
{id:"a057",topic:"zu-ni",kind:"conceito",q:"Como se pede “Não vá, por favor”?",opts:["{行|い}かずに ください","{行|い}かず ください","{行|い}かないで ください","{行|い}かなくに ください"],ans:2,why:"Para pedir, usa-se **～ないで ください**. A forma ずに não serve para pedidos."},
{id:"a058",topic:"te-kuru-iku",kind:"traducao",q:"O que quer dizer コンビニで {飲|の}み{物|もの}を {買|か}って きます。?",opts:["Comprei uma bebida e vim para cá","Vou ao mercadinho comprar uma bebida (e volto já)","Estou comprando uma bebida agora","Costumo comprar bebida no mercadinho"],ans:1,why:"{買|か}って くる é **ir comprar e voltar**. Não é “comprar e vir para cá”."},
{id:"a059",topic:"te-kuru-iku",kind:"conceito",q:"Complete para dizer “levar”: この {荷物|にもつ}を {駅|えき}まで {持|も}って（　）。",opts:["きます","いきます","います","あげます"],ans:1,why:"**Levar = {持|も}って いく; trazer = {持|も}って くる.** Aqui a bagagem vai até a estação."},
{id:"a060",topic:"te-kuru-iku",kind:"conceito",q:"Qual frase quer dizer “O número de pessoas vem aumentando (até agora)”?",opts:["{人|ひと}が {増|ふ}えて いきます","{人|ひと}が {増|ふ}えて あります","{人|ひと}が {増|ふ}えて しまいます","{人|ひと}が {増|ふ}えて きました"],ans:3,why:"**～て きた** olha para o passado até agora: {増|ふ}えて きた. **～て いく** olha para o futuro."},
{id:"a061",topic:"beki",kind:"forma",q:"Como se diz “Você não deveria ir”?",opts:["{行|い}かないべきです","{行|い}く べきではありません","{行|い}かなかった べきです","{行|い}った べきです"],ans:1,why:"Não existe ✗ ～ないべき. O negativo é **～べきでは ない**: {行|い}く べきでは ありません."},
{id:"a062",topic:"beki",kind:"forma",q:"Qual é a forma de する antes de べき?",opts:["しべき","せべき","するべき (ou すべき)","さべき"],ans:2,why:"**する → するべき** ou **すべき**; as duas existem, e すべき é mais formal."},
{id:"a063",topic:"beki",kind:"traducao",q:"O que quer dizer {言|い}う べきだった。?",opts:["Eu devia ter dito (e não disse)","Eu devo dizer","Não devo dizer","Talvez eu tenha dito"],ans:0,why:"**～べきだった** é lamento sobre o passado: devia ter dito, e a pessoa não disse."},
{id:"a064",topic:"mono-koto-da",kind:"traducao",q:"O que quer dizer よく {遊|あそ}んだ ものだ。?",opts:["Acabei de brincar","Brinquei uma vez ontem","Eu brincava muito (lembrança de um hábito)","Não devo brincar"],ans:2,why:"**～た ものだ** lembra um hábito repetido do passado, e não um evento único."},
{id:"a065",topic:"mono-koto-da",kind:"conceito",q:"Qual frase dá um conselho direto: “O melhor é praticar todo dia”?",opts:["{毎日|まいにち} {練習|れんしゅう}する ものだ","{毎日|まいにち} {練習|れんしゅう}した ものだ","{毎日|まいにち} {練習|れんしゅう}する はずだ","{毎日|まいにち} {練習|れんしゅう}する ことだ"],ans:3,why:"**～ことだ** dá um conselho direto: “o melhor é ~”. ものだ fala de tendências gerais ou de lembranças."},
{id:"a066",topic:"mono-koto-da",kind:"conceito",q:"Qual frase quer dizer “Não se deve falar mal dos outros”?",opts:["{人|ひと}の {悪口|わるぐち}を {言|い}う ことだ","{人|ひと}の {悪口|わるぐち}を {言|い}う ものではない","{人|ひと}の {悪口|わるぐち}を {言|い}った ものだ","{人|ひと}の {悪口|わるぐち}を {言|い}う はずだ"],ans:1,why:"**～ものでは ない** diz que algo não se deve fazer. {言|い}う ことだ diria o contrário: “o melhor é falar mal”."},
{id:"a067",topic:"meirei-kinshi",kind:"forma",q:"Qual é o imperativo de {食|た}べる?",opts:["{食|た}べれ","{食|た}べな","{食|た}べろ","{食|た}べて"],ans:2,why:"Nos verbos ichidan, **る → ろ**: {食|た}べる → {食|た}べろ."},
{id:"a068",topic:"meirei-kinshi",kind:"forma",q:"Qual é o imperativo de {来|く}る?",opts:["{来|き}ろ","{来|く}れ","{来|こ}ろ","{来|こ}い"],ans:3,why:"O imperativo de くる é **こい**, e o de する é しろ."},
{id:"a069",topic:"meirei-kinshi",kind:"conceito",q:"Qual forma é adequada para pedir a um cliente “Aguarde, por favor”?",opts:["{待|ま}て","{待|ま}ちなさい","{待|ま}って ください","{待|ま}つな"],ans:2,why:"O imperativo seco é brusco e ～なさい é de quem tem autoridade. Com clientes, usa-se **～て ください**."},
{id:"a070",topic:"sasete-itadaku",kind:"forma",q:"Qual é a forma correta de {休|やす}む em ～させて いただきます (“vou descansar, com a sua permissão”)?",opts:["{休|やす}まれて いただきます","{休|やす}ませて いただきます","{休|やす}めて いただきます","{休|やす}みさせて いただきます"],ans:1,why:"Forma-se o causativo na forma て e acrescenta-se いただく: {休|やす}む → {休|やす}ませて いただきます."},
{id:"a071",topic:"sasete-itadaku",kind:"conceito",q:"Qual é a diferença entre ～て いただく e ～**させて** いただく?",opts:["Os dois querem dizer “receber um favor”","{教|おし}えて いただく: eu explico com permissão; {説明|せつめい}させて いただく: recebo o favor de me ensinarem","{教|おし}えて いただく: recebo o favor de alguém me ensinar; {説明|せつめい}させて いただく: eu explico, com a sua permissão","Só muda o tempo verbal"],ans:2,why:"～て いただく é receber o favor de alguém fazer algo; ～させて いただく é **eu** fazer, com a permissão do outro."},
{id:"a072",topic:"sasete-itadaku",kind:"conceito",q:"Qual frase quer dizer “Deixe-me ver”?",opts:["{見|み}せて ください","{見|み}させて ください","{見|み}て ください","{見|み}ないで ください"],ans:1,why:"{見|み}**させて** (causativo de {見|み}る) é “deixe-me ver”. {見|み}**せて** é “mostre”."},
{id:"a073",topic:"tomo-ni",kind:"conceito",q:"Qual é o nível de formalidade de ～とともに e ～に{伴|ともな}って?",opts:["Informais e coloquiais, usados entre amigos","Gíria de jovens","Usados só na fala, nunca na escrita","Formais e escritos, comuns em jornais e textos"],ans:3,why:"As duas são expressões **formais e escritas**. Na conversa, usam-se と いっしょに e につれて."},
{id:"a074",topic:"tomo-ni",kind:"conceito",q:"Qual é o jeito mais natural, na conversa, de dizer “junto com um amigo”?",opts:["{友|とも}だちと ともに","{友|とも}だちに {伴|ともな}って","{友|とも}だちと いっしょに","{友|とも}だちに {伴|ともな}い"],ans:2,why:"Com pessoas, no dia a dia, diz-se **と いっしょに**. とともに soa duro e formal."},
{id:"a075",topic:"tomo-ni",kind:"conceito",q:"Complete: {人口|じんこう}の {増加|ぞうか}（　）、{家|いえ}が {足|た}りません。 (“com o aumento da população”)",opts:["に{伴|ともな}い","について","として","において"],ans:0,why:"**に{伴|ともな}い** liga uma mudança em andamento (o aumento) ao que acontece junto com ela."},
{id:"a076",topic:"bakari-ka",kind:"conceito",q:"Qual frase usa corretamente ～ばかりか?",opts:["{安|やす}い ばかりか、おいしくないです","{安|やす}い ばかりか、おいしいです","{安|やす}い ばかりか、{来|き}て ください","{安|やす}い ばかりか、{高|たか}いです"],ans:1,why:"Os dois fatos vão na **mesma direção** (barato e gostoso). A segunda parte descreve um fato, não um pedido."},
{id:"a077",topic:"bakari-ka",kind:"conceito",q:"Qual deve ser a relação entre os dois fatos em ～ばかりか?",opts:["Mesma direção, e o segundo é mais forte","Direções opostas","Mesmo peso, sem diferença","O segundo é sempre um pedido"],ans:0,why:"Os dois fatos seguem a mesma direção e o segundo é **mais forte** que o primeiro. Se têm o mesmo peso, usa-se ～だけでなく."},
{id:"a078",topic:"bakari-ka",kind:"conceito",q:"Qual destas expressões de “não só ~, mas também ~” é a mais formal e escrita?",opts:["～だけでなく","～ばかりか","～しか ない","～のみならず"],ans:3,why:"**～のみならず** é a mais formal e escrita. ～だけでなく é neutro e ～ばかりか é mais forte."},
{id:"a079",topic:"keigo-teineigo",kind:"conceito",q:"Como se diz “Aqui é a recepção” de forma polida?",opts:["こちらが {受付|うけつけ}で いらっしゃいます","こちらが {受付|うけつけ}で ございます","こちらが {受付|うけつけ}で おります","こちらが {受付|うけつけ}で なさいます"],ans:1,why:"**で ございます** é o polido de です, para coisas e lugares. いらっしゃいます é para pessoas."},
{id:"a080",topic:"keigo-teineigo",kind:"conceito",q:"Qual opção segue a tendência “ご + palavra de origem chinesa”?",opts:["ご{家族|かぞく}","お{家族|かぞく}","ご{茶|ちゃ}","ご{水|みず}"],ans:0,why:"{家族|かぞく} é de origem chinesa e leva **ご**. Palavras japonesas, como お{茶|ちゃ} e お{水|みず}, levam お."},
{id:"a081",topic:"keigo-teineigo",kind:"conceito",q:"Qual destas formas soa estranha?",opts:["お{茶|ちゃ}","お{金|かね}","お{水|みず}","おコーヒー"],ans:3,why:"Palavras de origem estrangeira, como コーヒー, quase nunca levam お. As outras são palavras consagradas."},
{id:"a082",topic:"keigo-sonkeigo",kind:"conceito",q:"Qual é o verbo de respeito para {言|い}う, usado para o(a) professor(a) ou o(a) cliente?",opts:["おっしゃる","{申|もう}す","{伺|うかが}う","{拝見|はいけん}する"],ans:0,why:"**おっしゃる** é o verbo de respeito de {言|い}う. {申|もう}す é humilde, para o seu próprio lado."},
{id:"a083",topic:"keigo-sonkeigo",kind:"forma",q:"Qual é a forma ます de いらっしゃる?",opts:["いらっしゃります","いらっしゃるます","いらっしゃいます","いらっしゃいります"],ans:2,why:"いらっしゃる, おっしゃる, なさる e くださる têm o ます irregular: **いらっしゃいます**."},
{id:"a084",topic:"keigo-sonkeigo",kind:"conceito",q:"Qual frase, com o(a) professor(a) como sujeito, está correta?",opts:["{先生|せんせい}が {申|もう}しました","{先生|せんせい}が {伺|うかが}いました","{先生|せんせい}が いたしました","{先生|せんせい}が おっしゃいました"],ans:3,why:"Para elevar o(a) professor(a), usa-se **おっしゃいました**. {申|もう}す, {伺|うかが}う e いたす são humildes."},
{id:"a085",topic:"keigo-kenjougo",kind:"conceito",q:"Como se diz de forma humilde “Eu me chamo Yamada”?",opts:["{山田|やまだ}と おっしゃいます","{山田|やまだ}と {申|もう}します","{山田|やまだ}と いらっしゃいます","{山田|やまだ}と {召|め}し{上|あ}がります"],ans:1,why:"**{申|もう}す** é o verbo humilde de {言|い}う: {山田|やまだ}と {申|もう}します."},
{id:"a086",topic:"keigo-kenjougo",kind:"conceito",q:"Qual é o verbo humilde que quer dizer “visitar”?",opts:["いらっしゃる","{伺|うかが}う","おっしゃる","ご{覧|らん}に なる"],ans:1,why:"**{伺|うかが}う** é o verbo humilde para visitar (e para perguntar). Os outros são de respeito."},
{id:"a087",topic:"keigo-kenjougo",kind:"conceito",q:"Falando com alguém de fora da empresa, qual frase sobre o seu próprio chefe está correta?",opts:["{社長|しゃちょう}の {田中|たなか}さんは まいります","{社長|しゃちょう}の {田中|たなか}さんが いらっしゃいます","{社長|しゃちょう}の {田中|たなか}{様|さま}は おいでに なります","{社長|しゃちょう}の {田中|たなか}は まいります"],ans:3,why:"Com gente de fora, o seu lado é humilde e **sem さん**: {田中|たなか}は まいります."},
// FIM-AVANCADO
]
};
